return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'kn','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-02T07:33:51+00:00','po-revision-date'=>'2026-09-02T07:33:51+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'WordPress ಗಾಗಿ ಸಂಪೂರ್ಣ ಕ್ಯಾಶಿಂಗ್ ಮತ್ತು ಆಪ್ಟಿಮೈಸೇಶನ್ ಇಂಜಿನ್: ಫುಲ್-ಪೇಜ್ ಕ್ಯಾಶ್, ಆಬ್ಜೆಕ್ಟ್ ಕ್ಯಾಶ್, ಡೇಟಾಬೇಸ್ ಕ್ಲೀನಪ್ ಮತ್ತು CSS/JS ಆಪ್ಟಿಮೈಸೇಶನ್. ನಿಮ್ಮ ಹೋಸ್ಟ್ ತನ್ನದೇ ಆದ ಕ್ಯಾಶ್ ಲೇಯರ್ ಅನ್ನು ಒದಗಿಸದಿದ್ದಾಗ ಇದನ್ನು ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿ — Zinn Digital® ಹೋಸ್ಟಿಂಗ್‌ನಲ್ಲಿ ಇದರ ಬದಲಿಗೆ Zinn® Cache ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿ. ಫುಲ್-ಪೇಜ್ ಕ್ಯಾಶಿಂಗ್‌ಗೆ LSCache ಮಾಡ್ಯೂಲ್ ಹೊಂದಿರುವ LiteSpeed ಅಥವಾ OpenLiteSpeed ಸರ್ವರ್ ಅಗತ್ಯವಿದೆ. ಇದು LiteSpeed Cache ಪ್ಲಗಿನ್‌ನ GPLv3 ಫೋರ್ಕ್ ಆಗಿದೆ.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d ಗಂಟೆಗಳು','%d hour'=>'%d ಗಂಟೆ','%d minutes'=>'%d ನಿಮಿಷಗಳು','%d minute'=>'%d ನಿಮಿಷ','Purged All!'=>'ಎಲ್ಲವನ್ನೂ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ!','Purged the blog!'=>'ಬ್ಲಾಗ್ ಅನ್ನು ತೆರವುಗೊಳಿಸಲಾಗಿದೆ!','Purged the URL!'=>'URL ಅನ್ನು ತೆರವುಗೊಳಿಸಲಾಗಿದೆ!','Purged!'=>'ಪೂರ್ಣವಾಗಿ ಅಳಿಸಲಾಗಿದೆ!','Failed to upgrade.'=>'ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡಲು ವಿಫಲವಾಗಿದೆ.','Upgraded successfully.'=>'ಯಶಸ್ವಿಯಾಗಿ ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡಲಾಗಿದೆ.','Dashboard'=>'ಡ್ಯಾಶ್‌ಬೋರ್ಡ್','OptimaX'=>'OptimaX','Presets'=>'ಪೂರ್ವನಿಗದಿಗಳು','General'=>'ಸಾಮಾನ್ಯ','Cache'=>'ಕ್ಯಾಶ್','CDN'=>'CDN','Image Optimization'=>'ಚಿತ್ರ ಆಪ್ಟಿಮೈಸೇಶನ್','Page Optimization'=>'ಪುಟ ಆಪ್ಟಿಮೈಸೇಶನ್','Database'=>'ಡೇಟಾಬೇಸ್','Crawler'=>'ಕ್ರಾಮ್ಲರ್','Toolbox'=>'ಉಪಕರಣ ಪೆಟ್ಟಿಗೆ','Cookie Name'=>'ಕುಕೀ ಹೆಸರು','Cookie Values'=>'ಕುಕಿ ಮೌಲ್ಯಗಳು','Remove cookie simulation'=>'कुकी ಸಿಮ್ಯುಲೇಶನ್ ಅನ್ನು ತೆಗೆದುಹಾಕಿ','Add new cookie to simulate'=>'ಸಿಮ್ಯುಲೇಟ್ ಮಾಡಲು ಹೊಸ ಕುಕಿಯನ್ನು ಸೇರಿಸಿ','CDN URL to be used. For example, %s'=>'ಬಳಸಬೇಕಾದ ಸಿಡಿಎನ್ (CDN) ಯುಆರ್‌ಎಲ್ (URL). ಉದಾಹರಣೆಗೆ, %s','Remove CDN URL'=>'CDN URL ಅನ್ನು ತೆಗೆದುಹಾಕಿ','Add new CDN URL'=>'ಹೊಸ CDN URL ಅನ್ನು ಸೇರಿಸಿ','ON'=>'ಚಾಲನೆಗೊಳ್ಳುತ್ತಿದೆ','OFF'=>'ಆಫ್','Settings'=>'ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Dismiss'=>'ವಿಸರ್ಜಿಸಿ','Save Changes'=>'ಬದಲಾವಣೆಗಳನ್ನು ಉಳಿಸಿ','This value is overwritten by the %s variable.'=>'ಈ ಮೌಲ್ಯವನ್ನು %s ವೇರಿಯೇಬಲ್‌ನಿಂದ ತಿದ್ದಿಬರೆಯಲಾಗಿದೆ.','This value is overwritten by the filter.'=>'ಈ ಮೌಲ್ಯವನ್ನು ಫಿಲ್ಟರ್‌ನಿಂದ ತಿದ್ದಿ ಬರೆಯಲಾಗಿದೆ.','This value is overwritten by the PHP constant %s.'=>'ಈ ಮೌಲ್ಯವನ್ನು PHP ಸ್ಥಿರಾಂಕ %s ಮೂಲಕ ತಿದ್ದಿಬರೆಯಲಾಗಿದೆ.','This value is overwritten by the primary site setting.'=>'ಈ ಮೌಲ್ಯವನ್ನು ಪ್ರಾಥಮಿಕ ಸೈಟ್ ಸೆಟ್ಟಿಂಗ್‌ನಿಂದ ತಿದ್ದಿಬರೆಯಲಾಗಿದೆ.','This value is overwritten by the Network setting.'=>'ಈ ಮೌಲ್ಯವನ್ನು ನೆಟ್‌ವರ್ಕ್ ಸೆಟ್ಟಿಂಗ್‌ನಿಂದ ತಿದ್ದಿಬರೆಯಲಾಗಿದೆ.','Currently set to %s'=>'ಪ್ರಸ್ತುತ %s ಗೆ ಹೊಂದಿಸಲಾಗಿದೆ','Value from filter applied'=>'ಅನ್ವಯಿಸಲಾದ ಫಿಲ್ಟರ್‌ನಿಂದ ಮೌಲ್ಯ','seconds'=>'ಸೆಕೆಂಡುಗಳು','Default value'=>'ಪೂರ್ವನಿಯೋಜಿತ ಮೌಲ್ಯ','Invalid rewrite rule'=>'ಅಮೂರ್ಯ ರಿರೈಟ್ ನಿಯಮ','Path must end with %s'=>'ಪಾಥ್ %s ನೊಂದಿಗೆ ಕೊನೆಗೊಳ್ಳಬೇಕು','Minimum value'=>'ಕನಿಷ್ಠ ಮೌಲ್ಯ','Maximum value'=>'ಗರಿಷ್ಠ ಮೌಲ್ಯ','Zero, or'=>'ಶೂನ್ಯ, ಅಥವಾ','Larger than'=>'ಇದಕ್ಕಿಂತ ದೊಡ್ಡದು','Smaller than'=>'ಕಿಂತ ಚಿಕ್ಕದು','Value range'=>'ಮೌಲ್ಯದ ಶ್ರೇಣಿ','Invalid IP'=>'ಅಮಾನ್ಯ IP','API'=>'ಎಪಿಐ','Server variable(s) %s available to override this setting.'=>'ಈ ಸೆಟ್ಟಿಂಗ್ ಅನ್ನು ಮೇಲಿರುವಂತೆ ಮಾಡಲು ಸರ್ವರ್ ವೇರಿಯೇಬಲ್(ಗಳು) %s ಲಭ್ಯವಿವೆ.','The URLs will be compared to the REQUEST_URI server variable.'=>'URL ಗಳನ್ನು REQUEST_URI ಸರ್ವರ್ ವೇರಿಯೇಬಲ್‌ನೊಂದಿಗೆ ಹೋಲಿಸಲಾಗುತ್ತದೆ.','For example, for %1$s, %2$s can be used here.'=>'ಉದಾಹರಣೆಗೆ, %1$s ಗಾಗಿ, ಇಲ್ಲಿ %2$s ಅನ್ನು ಬಳಸಬಹುದು.','To match the beginning, add %s to the beginning of the item.'=>'ಪ್ರಾರಂಭವನ್ನು ಹೊಂದಿಸಲು, ಐಟಂನ ಪ್ರಾರಂಭಕ್ಕೆ %s ಸೇರಿಸಿ.','To do an exact match, add %s to the end of the URL.'=>'ಖಚಿತ ಹೊಂದಾಣಿಕೆಗಾಗಿ, URL ನ ಕೊನೆಗೆ %s ಅನ್ನು ಸೇರಿಸಿ.','One per line.'=>'ಪ್ರತಿ ಸಾಲಿಗೆ ಒಂದರಂತೆ.','%s groups'=>'%s ಗುಂಪುಗಳು','%s images'=>'%s ಚಿತ್ರಗಳು','%s group'=>'%s ಗುಂಪು','%s image'=>'%s ಚಿತ್ರ','No fields'=>'ಯಾವ ಕ್ಷೇತ್ರಗಳೂ ಇಲ್ಲ','The user with id %s has editor access, which is not allowed for the role simulator.'=>'%s ಐಡಿ ಹೊಂದಿರುವ ಬಳಕೆದಾರರಿಗೆ ಸಂಪಾದಕರ ಪ್ರವೇಶವಿದೆ, ಇದು ರೋಲ್ ಸಿಮ್ಯುಲೇಟರ್‌ಗೆ ಅನುಮತಿಸಲಾಗುವುದಿಲ್ಲ.','Options saved.'=>'ಆಯ್ಕೆಗಳನ್ನು ಉಳಿಸಲಾಗಿದೆ.','Notified Cloudflare to set development mode to %s successfully.'=>'Development mode ಅನ್ನು %s ಗೆ ಹೊಂದಿಸಲು Cloudflare ಗೆ ಯಶಸ್ವಿಯಾಗಿ ಸೂಚಿಸಲಾಗಿದೆ.','Cloudflare API is set to off.'=>'ಕ್ಲೌಡ್‌ಫ್ಲೇರ್ (Cloudflare) API ಅನ್ನು ಆಫ್‌ಗೆ ಹೊಂದಿಸಲಾಗಿದೆ.','Notified Cloudflare to purge all successfully.'=>'ಎಲ್ಲವನ್ನೂ ಯಶಸ್ವಿಯಾಗಿ ಶುದ್ಧೀಕರಿಸಲು Cloudflare ಗೆ ಸೂಚಿಸಲಾಗಿದೆ.','No available Cloudflare zone'=>'ಯಾವುದೇ ಲಭ್ಯವಿರುವ Cloudflare zone ಇಲ್ಲ','Failed to communicate with Cloudflare'=>'ಕ್ಲೌಡ್‌ಫ್ಲೇರ್ (Cloudflare) ಜೊತೆ ಸಂವಹನ ನಡೆಸಲು ವಿಫಲವಾಗಿದೆ','Communicated with Cloudflare successfully.'=>'ಕ್ಲೌಡ್‌ಫ್ಲೇರ್ (Cloudflare) ಜೊತೆ ಯಶಸ್ವಿಯಾಗಿ ಸಂವಹನ ನಡೆಸಲಾಗಿದೆ.','Failed to validate %s activation data.'=>'%s ಸಕ್ರಿಯಗೊಳಿಸುವ ಡೇಟಾವನ್ನು ಮೌಲ್ಯಕರಿಸುವಲ್ಲಿ ವಿಫಲವಾಗಿದೆ.','Failed to parse %s activation status.'=>'%s ಸಕ್ರಿಯಗೊಳಿಸುವ ಸ್ಥಿತಿಯನ್ನು ಪಾರ್ಸ್ ಮಾಡಲು ವಿಫಲವಾಗಿದೆ.','%s activation data expired.'=>'%s ಸಕ್ರಿಯಗೊಳಿಸುವ ಡೇಟಾ ಅವಧಿ ಮುಗಿದಿದೆ.','Congratulations, %s successfully set this domain up for the anonymous online services.'=>'ಅಭಿನಂದನೆಗಳು, %s ಈ ಡೊಮೇನ್ ಅನ್ನು ಅನಾಮಧೇಯ ಆನ್‌ಲೈನ್ ಸೇವೆಗಳಿಗಾಗಿ ಯಶಸ್ವಿಯಾಗಿ ಕಾನ್ಫಿಗರ್ ಮಾಡಿದ್ದಾರೆ.','Congratulations, %s successfully set this domain up for the online services.'=>'ಅಭಿನಂದನೆಗಳು, %s ಆನ್‌ಲೈನ್ ಸೇವೆಗಳಿಗಾಗಿ ಈ ಡೊಮೇನ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಕಾನ್ಫಿಗರ್ ಮಾಡಿದ್ದಾರೆ.','Congratulations, %s successfully set this domain up for the online services with CDN service.'=>'ಅ ಅಭಿನಂದನೆಗಳು, %s ಈ ಡೊಮೇನ್ ಅನ್ನು ಸಿಡಿಎನ್ ಸೇವೆಯೊಂದಿಗೆ ಆನ್‌ಲೈನ್ ಸೇವೆಗಳಿಗಾಗಿ ಯಶಸ್ವಿಯಾಗಿ ಹೊಂದಿಸಿದೆ.','Site not recognized. QUIC.cloud deactivated automatically. Please reactivate your QUIC.cloud account.'=>'ಸೈಟ್ ಗುರುತಿಸಲಾಗಿಲ್ಲ. QUIC.cloud ಸ್ವಯಂಚಾಲಿತವಾಗಿ ನಿಷ್ಕ್ರಿಯಗೊಂಡಿದೆ. ದಯವಿಟ್ಟು ನಿಮ್ಮ QUIC.cloud ಖಾತೆಯನ್ನು ಮರುಸಕ್ರಿಯಗೊಳಿಸಿ.','Click here to proceed.'=>'ಮುಂದುವರಿಯಲು ಇಲ್ಲಿ ಕ್ಲಿಕ್ ಮಾಡಿ.','QUIC.cloud\'s access to your WP REST API seems to be blocked.'=>'QUIC.cloud ಗೆ ನಿಮ್ಮ WP REST API ಯ ಪ್ರವೇಶವು ನಿರ್ಬಂಧಿಸಲ್ಪಟ್ಟಿರುವಂತೆ ತೋರುತ್ತಿದೆ.','Failed to get echo data from WPAPI'=>'WPAPI ನಿಂದ ಎಕೋ ಡೇಟಾವನ್ನು ಪಡೆಯಲು ವಿಫಲವಾಗಿದೆ','You need to set the %1$s first. Please use the command %2$s to set.'=>'ನೀವು ಮೊದಲು %1$s ಅನ್ನು ಹೊಂದಿಸಬೇಕು. ದಯವಿಟ್ಟು ಹೊಂದಿಸಲು %2$s ಆಜ್ಞೆಯನ್ನು ಬಳಸಿ.','Server IP'=>'ಸರ್ವರ್ ಐಪಿ','You need to activate QC first.'=>'ನೀವು ಮೊದಲು ಕ್ಯೂಸಿ (QC) ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಬೇಕು.','Cert or key file does not exist.'=>'ಪ್ರಮಾಣಪತ್ರ ಅಥವಾ ಕೀ ಫೈಲ್ ಅಸ್ತಿತ್ವದಲ್ಲಿಲ್ಲ.','Reset %s activation successfully.'=>'%s ಸಕ್ರಿಯಗೊಳಿಸುವಿಕೆಯನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಮರುಹೊಂದಿಸಲಾಗಿದೆ.','Linked to QUIC.cloud preview environment, for testing purpose only.'=>'QUIC.cloud ಪೂರ್ವವೀಕ್ಷಣೆ ಪರಿಸರಕ್ಕೆ ಲಿಂಕ್ ಮಾಡಲಾಗಿದೆ, ಪರೀಕ್ಷಾ ಉದ್ದೇಶಕ್ಕಾಗಿ ಮಾತ್ರ.','Cloud Error'=>'ಕ್ಲೌಡ್ ದೋಷ','No available Cloud Node after checked server load.'=>'ಸರ್ವರ್ ಲೋಕಲ್ ಅನ್ನು ಪರಿಶೀಲಿಸಿದ ನಂತರ ಯಾವುದೇ ಕ್ಲೌಡ್ ನೋಡ್ ಲಭ್ಯವಿಲ್ಲ.','No available Cloud Node.'=>'ಯಾವ ಲಭ್ಯವಿರುವ ಕ್ಲೌಡ್ ನೋಡ್ ಇಲ್ಲ.','In order to use QC services, need a real domain name, cannot use an IP.'=>'QC ಸೇವೆಗಳನ್ನು ಬಳಸಲು, ನಿಜವಾದ ಡೊಮೇನ್ ಹೆಸರು ಅಗತ್ಯವಿದೆ, ಐಪಿಯನ್ನು ಬಳಸಲಾಗುವುದಿಲ್ಲ.','Please try after %1$s for service %2$s.'=>'ಸೇವೆ %2$s ಗಾಗಿ ದಯವಿಟ್ಟು %1$s ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','Failed to request via WordPress'=>'WordPress ಮೂಲಕ ವಿನಂತಿಸಲು ವಿಫಲವಾಗಿದೆ','Cloud server refused the current request due to unpulled images. Please pull the images first.'=>'ಅನ್‌ಪುಲ್ ಮಾಡಿದ ಚಿತ್ರಗಳ ಕಾರಣದಿಂದ ಕ್ಲೌಡ್ ಸರ್ವರ್ ಪ್ರಸ್ತುತ ವಿನಂತಿಯನ್ನು ತಿರಸ್ಕರಿಸಿದೆ. ದಯವಿಟ್ಟು ಮೊದಲು ಚಿತ್ರಗಳನ್ನು pull ಮಾಡಿ.','Your domain_key has been temporarily blocklisted to prevent abuse. You may contact support at QUIC.cloud to learn more.'=>'ಅಪರೂಪದ ದುರ್ಬಳಕೆಯನ್ನು ತಡೆಯಲು ನಿಮ್ಮ domain_key ಅನ್ನು ತಾತ್ಕಾಲಿಕವಾಗಿ ಬ್ಲಾಕ್‌ಲಿಸ್ಟ್ ಮಾಡಲಾಗಿದೆ. ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ನೀವು QUIC.cloud ನಲ್ಲಿ ಬೆಂಬಲ ತಂಡವನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು.','Cloud server refused the current request due to rate limiting. Please try again later.'=>'ದರ ಮಿತಿಯ ಕಾರಣದಿಂದ ಕ್ಲೌಡ್ ಸರ್ವರ್ ಪ್ರಸ್ತುತ ವಿನಂತಿಯನ್ನು ತಿರಸ್ಕರಿಸಿದೆ. ದಯವಿಟ್ಟು ನಂತರ ಪುನಃ ಪ್ರಯತ್ನಿಸಿ.','Redetected node'=>'ಮರುಪತ್ತೆಹೊಂದಿದ ನೋಡ್','We are working hard to improve your online service experience. The service will be unavailable while we work. We apologize for any inconvenience.'=>'ನಿಮ್ಮ ಆನ್‌ಲೈನ್ ಸೇವಾ ಅನುಭವವನ್ನು ಸುಧಾರಿಸಲು ನಾವು ಶ್ರಮಿಸುತ್ತಿದ್ದೇವೆ. ನಾವು ಕೆಲಸ ಮಾಡುವಾಗ ಸೇವೆಯು ಲಭ್ಯವಿರುವುದಿಲ್ಲ. ಯಾವುದೇ ಅನಾನುಕೂಲತೆಗಾಗಿ ನಾವು ಕ್ಷಮೆಯಾಚಿಸುತ್ತೇವೆ.','Message from QUIC.cloud server'=>'QUIC.cloud ಸರ್ವರ್‌ನಿಂದ ಸಂದೇಶ','Good news from QUIC.cloud server'=>'QUIC.cloud ಸರ್ವರ್‌ನಿಂದ ಒಳ್ಳೆಯ ಸುದ್ದಿ','%1$s plugin version %2$s required for this action.'=>'ಈ ಕ್ರಿಯೆಗೆ %1$s ಪ್ಲಗಿನ್ ಆವೃತ್ತಿ %2$s ಅಗತ್ಯವಿದೆ.','Failed to communicate with QUIC.cloud server'=>'QUIC.cloud ಸರ್ವರ್‌ನೊಂದಿಗೆ ಸಂವಹನ ನಡೆಸಲು ವಿಫಲವಾಗಿದೆ','Sync QUIC.cloud status successfully.'=>'QUIC.cloud ಸ್ಥಿತಿಯನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಸಿಂಕ್ ಮಾಡಲಾಗಿದೆ.','Sync credit allowance with Cloud Server successfully.'=>'ಕ್ಲೌಡ್ ಸರ್ವರ್‌ನೊಂದಿಗೆ ಕ್ರೆಡಿಟ್ ಭತ್ಯೆಯನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಸಿಂಕ್ ಮಾಡಲಾಗಿದೆ.','Saving option failed. IPv4 only for %s.'=>'ಉಳಿಸುವ ಆಯ್ಕೆ ವಿಫಲವಾಗಿದೆ. %s ಗಾಗಿ ಕೇವಲ IPv4 ಮಾತ್ರ.','Changed setting successfully.'=>'setting ಯಶಸ್ವಾಗಿ ಬದಲಾಯಿಸಲಾಗಿದೆ.','Notified LiteSpeed Web Server to purge everything.'=>'ಎಲ್ಲವನ್ನೂ ತೆರವುಗೊಳಿಸಲು LiteSpeed Web Server ಗೆ ಸೂಚಿಸಲಾಗಿದೆ.','Notified LiteSpeed Web Server to purge the list.'=>'ಪಟ್ಟಿಯನ್ನು ಶುದ್ಧೀಕರಿಸಲು LiteSpeed Web Server ಗೆ ಸೂಚಿಸಲಾಗಿದೆ.','Sitemap cleaned successfully'=>'ಸೈಟ್‌ಮ್ಯಾಪ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ','No valid sitemap parsed for crawler.'=>'ಕ್ರಾಲರ್‌ಗಾಗಿ ಯಾವುದೇ ಮಾನ್ಯವಾದ ಸೈಟ್‌ಮ್ಯಾಪ್ ಪಾರ್ಸ್ ಮಾಡಲಾಗಿಲ್ಲ.','Sitemap created successfully: %d items'=>'ಸೈಟ್ ನಕ್ಷೆಯನ್ನು ಯಶಸ್ವಿಯಾಗಿ ರಚಿಸಲಾಗಿದೆ: %d ಐಟಂಗಳು','Crawler disabled list is cleared! All crawlers are set to active! '=>'ಕ್ರಾಲರ್ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದ ಪಟ್ಟಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ! ಎಲ್ಲಾ ಕ್ರಾಲರ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ!','Started async crawling'=>'ಅಸಿಂಕ್ ಕ್ರಾವ್ಲಿಂಗ್ ಪ್ರಾರಂಭಿಸಲಾಗಿದೆ','Guest'=>'ಅತಿಥಿ','Manually added to blocklist'=>'ಬ್ಲಾಕ್‌ಲಿಸ್ಟ್‌ಗೆ ಹಸ್ತಚಾಲಿತವಾಗಿ ಸೇರಿಸಲಾಗಿದೆ','Previously existed in blocklist'=>'ಈ ಮೊದಲು ಬ್ಲಾಕ್‌ಲಿಸ್ಟ್‌ನಲ್ಲಿ ಇತ್ತು','The database has been upgrading in the background since %s. This message will disappear once upgrade is complete.'=>'%s ನಿಂದ ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಡೇಟಾಬೇಸ್ ಅನ್ನು ನವೀಕರಿಸಲಾಗುತ್ತಿದೆ. ನವೀಕರಣವು ಪೂರ್ಣಗೊಂಡ ನಂತರ ಈ ಸಂದೇಶವು ಕಣ್ಮರೆಯಾಗುತ್ತದೆ.','Clean all successfully.'=>'ಎಲ್ಲವನ್ನೂ ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','Clean post revisions successfully.'=>'ಪೋಸ್ಟ್ ಪರಿಷ್ಕರಣೆಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','Clean orphaned post meta successfully.'=>'ಅನಾಥ ಪೋಸ್ಟ್ ಮೆಟಾವನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಿ.','Clean auto drafts successfully.'=>'ಸ್ವಯಂ ಡ್ರಾಫ್ಟ್‌ಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','Clean trashed posts and pages successfully.'=>'ಕಸದ ಬುಟ್ಟಿಗೆ ಹಾಕಿದ ಪೋಸ್ಟ್‌ಗಳು ಮತ್ತು ಪುಟಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಿ.','Clean spam comments successfully.'=>'ಸ್ಪ್ಯಾಮ್ ಕಾಮೆಂಟ್‌ಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','Clean trashed comments successfully.'=>'ಅಳಿಸಿದ ಕಾಮೆಂಟ್‌ಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','Clean trackbacks and pingbacks successfully.'=>'ಟ್ರ್ಯಾಕ್‌ಬ್ಯಾಕ್‌ಗಳು ಮತ್ತು ಪಿಂಗ್‌ಬ್ಯಾಕ್‌ಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','Clean expired transients successfully.'=>'ಅವಧಿ ಮೀರಿದ ಟ್ರಾನ್ಸಿಯೆಂಟ್‌ಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','Clean all transients successfully.'=>'ಎಲ್ಲಾ ಟ್ರಾನ್ಸಿಯೆಂಟ್‌ಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','Optimized all tables.'=>'ಎಲ್ಲಾ ಕೋಷ್ಟಕಗಳನ್ನು ಅತ್ಯುತ್ತಮವಾಗಿಸಲಾಗಿದೆ.','Converted to InnoDB successfully.'=>'InnoDB ಗೆ ಯಶಸ್ವಿಯಾಗಿ ಪರಿವರ್ತಿಸಲಾಗಿದೆ.','Invalid log type.'=>'ಅಮಾನ್ಯ ಲಾಗ್ ಪ್ರಕಾರ.','Log file not found.'=>'ಲಾಗ್ ಫೈಲ್ ಕಂಡುಬಂದಿಲ್ಲ.','This setting is %1$s for certain qualifying requests due to %2$s!'=>'ಈ ಸೆಟ್ಟಿಂಗ್ %2$s ಕಾರಣದಿಂದಾಗಿ ಕೆಲವು ಅರ್ಹ ವಿನಂತಿಗಳಿಗೆ %1$s ಆಗಿದೆ!','This setting will regenerate crawler list and clear the disabled list!'=>'ಈ ಸೆಟ್ಟಿಂಗ್ ಕ್ರಾwler ಪಟ್ಟಿಯನ್ನು ಮರುಸೃಷ್ಟಿಸುತ್ತದೆ ಮತ್ತು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದ ಪಟ್ಟಿಯನ್ನು ತೆರವುಗೊಳಿಸುತ್ತದೆ!','This site utilizes caching in order to facilitate a faster response time and better user experience. Caching potentially stores a duplicate copy of every web page that is on display on this site. All cache files are temporary, and are never accessed by any third party, except as necessary to obtain technical support from the cache plugin vendor. Cache files expire on a schedule set by the site administrator, but may easily be purged by the admin before their natural expiration, if necessary. We may use QUIC.cloud services to process & cache your data temporarily.'=>'ವೇಗದ ಪ್ರತಿಕ್ರಿಯೆ ಸಮಯ ಮತ್ತು ಉತ್ತಮ ಬಳಕೆದಾರ ಅನುಭವವನ್ನು ಒದಗಿಸುವ ಸಲುವಾಗಿ ಈ ಸೈಟ್ ಕ್ಯಾಶಿಂಗ್ ಅನ್ನು ಬಳಸಿಕೊಳ್ಳುತ್ತದೆ. ಕ್ಯಾಶಿಂಗ್ ಈ ಸೈಟ್‌ನಲ್ಲಿ ಪ್ರದರ್ಶಿಸಲಾಗುವ ಪ್ರತಿಯೊಂದು ವೆಬ್ ಪುಟದ ನಕಲಿ ಪ್ರತಿಯನ್ನು ತಾತ್ಕಾಲಿಕವಾಗಿ ಸಂಗ್ರಹಿಸಬಹುದು. ಎಲ್ಲಾ ಕ್ಯಾಶ್ ಫೈಲ್‌ಗಳು ತಾತ್ಕಾಲಿಕವಾಗಿದ್ದು, ಕ್ಯಾಶ್ ಪ್ಲಗಿನ್ ಮಾರಾಟಗಾರರಿಂದ ತಾಂತ್ರಿಕ ಬೆಂಬಲವನ್ನು ಪಡೆಯಲು ಅಗತ್ಯವಿರುವಾಗ ಹೊರತುಪಡಿಸಿ, ಯಾವುದೇ ಮೂರನೇ ವ್ಯಕ್ತಿಯು ಇವುಗಳನ್ನು ಎಂದಿಗೂ ಪ್ರವೇಶಿಸುವುದಿಲ್ಲ. ಸೈಟ್ ನಿರ್ವಾಹಕರು ನಿಗದಿಪಡಿಸಿದ ವೇಳಾಪಟ್ಟಿಯಂತೆ ಕ್ಯಾಶ್ ಫೈಲ್‌ಗಳ ಅವಧಿ ಮುಕ್ತಾಯಗೊಳ್ಳುತ್ತದೆ, ಆದರೆ ಅಗತ್ಯವಿದ್ದರೆ ಅವುಗಳ ನೈಸರ್ಗಿಕ ಮುಕ್ತಾಯಕ್ಕೆ ಮುನ್ನವೇ ನಿರ್ವಾಹಕರು ಅವುಗಳನ್ನು ಸುಲಭವಾಗಿ ತೆರವುಗೊಳಿಸಬಹುದು. ನಿಮ್ಮ ಡೇಟಾವನ್ನು ತಾತ್ಕಾಲಿಕವಾಗಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲು ಮತ್ತು ಕ್ಯಾಶ್ ಮಾಡಲು ನಾವು QUIC.cloud ಸೇವೆಗಳನ್ನು ಬಳಸಬಹುದು.','Please see %s for more details.'=>'ಹೆಚ್ಚಿನ ವಿವರಗಳಿಗಾಗಿ ದಯವಿಟ್ಟು %s ಅನ್ನು ನೋಡಿ.','Learn More'=>'ಇನ್ನಷ್ಟು ತಿಳಿಯಿರಿ','Both full and partial strings can be used.'=>'ಪೂರ್ಣ ಮತ್ತು ಭಾಗಶಃ ಎರಡೂ ಸ್ಟ್ರಿಂಗ್‌ಗಳನ್ನು ಬಳಸಬಹುದು.','Both full URLs and partial strings can be used.'=>'ಪೂರ್ಣ URLಗಳು ಮತ್ತು ಭಾಗಶಃ ಸ್ಟ್ರಿಂಗ್‌ಗಳೆರಡನ್ನೂ ಬಳಸಬಹುದು.','This setting will edit the .htaccess file.'=>'ಈ ಸೆಟ್ಟಿಂಗ್ .htaccess ಫೈಲ್ ಅನ್ನು ಸಂಪಾದಿಸುತ್ತದೆ.','The queue is processed asynchronously. It may take time.'=>'ಸರತಿ ಸಾಲನ್ನು ಅಸಿಂಕ್ರೋನಸ್ ಆಗಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲಾಗುತ್ತದೆ. ಇದಕ್ಕೆ ಸಮಯ ತೆಗೆದುಕೊಳ್ಳಬಹುದು.','You will need to finish %s setup to use the online services.'=>'ಆನ್‌ಲೈನ್ ಸೇವೆಗಳನ್ನು ಬಳಸಲು ನೀವು %s ಸೆಟಪ್ ಅನ್ನು ಪೂರ್ಣಗೊಳಿಸಬೇಕಾಗುತ್ತದೆ.','Click here to set.'=>'ಸಾಧಿಸಲು ಇಲ್ಲಿ ಕ್ಲಿಕ್ ಮಾಡಿ.','You have used all of your daily quota for today.'=>'ಇಂದಿನ ನಿಮ್ಮ ದೈನಂದಿನ ಕೋಟಾವನ್ನು ನೀವು ಸಂಪೂರ್ಣವಾಗಿ ಬಳಸಿಕೊಂಡಿದ್ದೀರಿ.','Learn more or purchase additional quota.'=>'ಹೆಚ್ಚಿನ ಮಾಹಿತಿ ಪಡೆಯಿರಿ ಅಥವಾ ಹೆಚ್ಚುವರಿ ಕೋಟಾವನ್ನು ಖರೀದಿಸಿ.','You have used all of your quota left for current service this month.'=>'ಈ ತಿಂಗಳಲ್ಲಿ ನಿಮ್ಮ ಪ್ರಸ್ತುತ ಸೇವೆಗಾಗಿ ಉಳಿದಿರುವ ಕೋಟಾವನ್ನು ನೀವು ಸಂಪೂರ್ಣವಾಗಿ ಬಳಸಿಕೊಂಡಿದ್ದೀರಿ.','You have too many requested images, please try again in a few minutes.'=>'ನೀವು ಬಹಳಷ್ಟು ಚಿತ್ರಗಳನ್ನು ವಿನಂತಿಸಿದ್ದೀರಿ, ದಯವಿಟ್ಟು ಕೆಲವು ನಿಮಿಷಗಳ ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','You have images waiting to be pulled. Please wait for the automatic pull to complete, or pull them down manually now.'=>'ನಿಮ್ಮ ಚಿತ್ರಗಳು ಎಳೆದುಕೊಳ್ಳಲು ಕಾಯುತ್ತಿವೆ. ಸ್ವಯಂಚಾಲಿತ ಎಳೆಯುವಿಕೆ ಪೂರ್ಣಗೊಳ್ಳುವವರೆಗೆ ದಯವಿಟ್ಟು ನಿರೀಕ್ಷಿಸಿ, ಅಥವಾ ಈಗ ಅವುಗಳನ್ನು ಹಸ್ತಚಾಲಿತವಾಗಿ ಎಳೆದುಕೊಳ್ಳಿ.','The image list is empty.'=>'ಚಿತ್ರಗಳ ಪಟ್ಟಿ ಖಾಲಿಯಾಗಿದೆ.','Not enough parameters. Please check if the QUIC.cloud connection is set correctly'=>'ಸಾಕುgetParameters ಇಲ್ಲ. ದಯವಿಟ್ಟು QUIC.cloud ಸಂಪರ್ಕವನ್ನು ಸರಿಯಾಗಿ ಹೊಂದಿಸಲಾಗಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಿ','There is proceeding queue not pulled yet.'=>'ಇನ್ನೂ ಎಳೆದುಕೊಳ್ಳದ ಪ್ರಕ್ರಿಯೆಯ ಸರತಿಯಲ್ಲಿದೆ.','There is proceeding queue not pulled yet. Queue info: %s.'=>'ಇನ್ನೂ ಎಳೆದುಕೊಳ್ಳದ ಪ್ರಕ್ರಿಯೆಯ ಸರತಿಯಲ್ಲಿದೆ. ಸರತಿಯ ಸಾಲಿನ ಮಾಹಿತಿ: %s.','The site is not a valid alias on QUIC.cloud.'=>'ಸೈಟ್ QUIC.cloud ನಲ್ಲಿ ಮಾನ್ಯವಾದ ಅಲಿಯಾಸ್ ಅಲ್ಲ.','The site is not registered on QUIC.cloud.'=>'ಸೈಟ್ QUIC.cloud ನಲ್ಲಿ ನೋಂದಾಯಿಸಲ್ಪಟ್ಟಿಲ್ಲ.','The QUIC.cloud connection is not correct. Please try to sync your QUIC.cloud connection again.'=>'QUIC.cloud ಸಂಪರ್ಕವು ಸರಿಯಾಗಿಲ್ಲ. ದಯವಿಟ್ಟು ನಿಮ್ಮ QUIC.cloud ಸಂಪರ್ಕವನ್ನು ಮತ್ತೊಮ್ಮೆ ಸಿಂಕ್ ಮಾಡಲು ಪ್ರಯತ್ನಿಸಿ.','The current server is under heavy load.'=>'ಪ್ರಸ್ತುತ ಸರ್ವರ್ ಹೆಚ್ಚಿನ ಲೋಟ್‌ನಲ್ಲಿದೆ.','Online node needs to be redetected.'=>'ಆನ್‌ಲೈನ್ ನೋಡ್ ಅನ್ನು ಮರುಪತ್ತೆ ಮಾಡಬೇಕಾಗಿದೆ.','Credits are not enough to proceed the current request.'=>'ಪ್ರಸ್ತುತ ವಿನಂತಿಯನ್ನು ಮುಂದುವರಿಸಲು ಕ್ರೆಡಿಟ್‌ಗಳು ಸಾಕಾಗುವುದಿಲ್ಲ.','%s file not writable.'=>'%s ಕಡತವು ಬರೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ.','Could not find %1$s in %2$s.'=>'%2$s ನಲ್ಲಿ %1$s ಕಂಡುಬಂದಿಲ್ಲ.','Invalid login cookie. Please check the %s file.'=>'ಅಮಾನ್ಯ ಲಾಗಿನ್ ಕುಕಿ. ದಯವಿಟ್ಟು %s ಫೈಲ್ ಅನ್ನು ಪರಿಶೀಲಿಸಿ.','Failed to back up %s file, aborted changes.'=>'%s ಫೈಲ್ ಅನ್ನು ಬ್ಯಾಕಪ್ ಮಾಡಲು ವಿಫಲವಾಗಿದೆ, ಬದಲಾವಣೆಗಳನ್ನು ಕೈಬಿಡಲಾಗಿದೆ.','%s file not readable.'=>'%s ಕಡತವನ್ನು ಓದಲು ಸಾಧ್ಯವಿಲ್ಲ.','Failed to get %s file contents.'=>'%s ಫೈಲ್ ವಿಷಯಗಳನ್ನು ಪಡೆಯಲು ವಿಫಲವಾಗಿದೆ.','Failed to create table %1$s! SQL: %2$s.'=>'%1$s ಕೋಷ್ಟಕವನ್ನು ರಚಿಸಲು ವಿಫಲವಾಗಿದೆ! SQL: %2$s.','Crawler disabled by the server admin.'=>'ಸರ್ವರ್ ನಿರ್ವಾಹಕರಿಂದ ಕ್ರಾಲರ್ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.','Previous request too recent. Please try again later.'=>'ಹಿಂದಿನ ವಿನಂತಿಯು ತೀರಾ ಇತ್ತೀಚಿನದು. ದಯವಿಟ್ಟು ಸ್ವಲ್ಪ ಸಮಯದ ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','Previous request too recent. Please try again after %s.'=>'ಹಿಂದಿನ ವಿನಂತಿಯು ತುಂಬಾ ಇತ್ತೀಚಿನದಾಗಿದೆ. ದಯವಿಟ್ಟು %s ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','Your application is waiting for approval.'=>'ನಿಮ್ಮ ಅರ್ಜಿಯು ಅನುಮೋದನೆಗಾಗಿ ಕಾಯುತ್ತಿದೆ.','The callback validation to your domain failed due to hash mismatch.'=>'ಹ್ಯಾಶ್ ಮಿಸ್‌ಮ್ಯಾಚ್ ಕಾರಣದಿಂದಾಗಿ ನಿಮ್ಮ ಡೊಮೇನ್‌ಗೆ ಕಾಲ್‌ಬ್ಯಾಕ್ ಮೌಲ್ಯಮಾಪನ ವಿಫಲವಾಗಿದೆ.','The callback validation to your domain failed. Please make sure there is no firewall blocking our servers.'=>'ನಿಮ್ಮ ಡೊಮೇನ್‌ಗೆ ಕಾಲ್‌ಬ್ಯಾಕ್ ಮೌಲ್ಯಮಾಪನ ವಿಫಲಗೊಂಡಿದೆ. ನಮ್ಮ ಸರ್ವರ್‌ಗಳನ್ನು ನಿರ್ಬಂಧಿಸುವ ಯಾವುದೇ ಫೈರ್‌ವಾಲ್ ಇಲ್ಲ ಎಂಬುದನ್ನು ದಯವಿಟ್ಟು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.','The callback validation to your domain failed. Please make sure there is no firewall blocking our servers. Response code: '=>'ನಿಮ್ಮ ಡೊಮೇನ್‌ಗೆ ಕಾಲ್‌ಬ್ಯಾಕ್ ಮೌಲ್ಯಮಾಪನ ವಿಫಲಗೊಂಡಿದೆ. ನಮ್ಮ ಸರ್ವರ್‌ಗಳನ್ನು ನಿರ್ಬಂಧಿಸುವ ಯಾವುದೇ ಫೈರ್‌ವಾಲ್ ಇಲ್ಲ ಎಂಬುದನ್ನು ದಯವಿಟ್ಟು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ. ಪ್ರತಿಕ್ರಿಯೆ ಕೋಡ್:','Your domain has been forbidden from using our services due to a previous policy violation.'=>'ಹಿಂದಿನ ನೀತಿ ಉಲ್ಲಂಘನೆಯ ಕಾರಣದಿಂದಾಗಿ ನಿಮ್ಮ ಡೊಮೇನ್ ನಮ್ಮ ಸೇವೆಗಳನ್ನು ಬಳಸುವುದನ್ನು ನಿಷೇಧಿಸಲಾಗಿದೆ.','You cannot remove this DNS zone, because it is still in use. Please update the domain\'s nameservers, then try to delete this zone again, otherwise your site will become inaccessible.'=>'ನೀವು ಈ DNS ವಲಯವನ್ನು ತೆಗೆದುಹಾಕಲು ಸಾಧ್ಯವಿಲ್ಲ, ಏಕೆಂದರೆ ಇದು ಇನ್ನೂ ಬಳಕೆಯಲ್ಲಿದೆ. ದಯವಿಟ್ಟು ಡೊಮೇನ್‌ನ ನೇಮ್‌ಸರ್ವರ್‌ಗಳನ್ನು ಅಪ್‌ಡೇಟ್ ಮಾಡಿ, ನಂತರ ಈ ವಲಯವನ್ನು ಮತ್ತೆ ಅಳಿಸಲು ಪ್ರಯತ್ನಿಸಿ, ಇಲ್ಲದಿದ್ದರೆ ನಿಮ್ಮ ಸೈಟ್ ಅನ್ನು ಪ್ರವೇಶಿಸಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ.','Unknown error'=>'ಅಜ್ಞಾತ ದೋಷ','Filename is empty!'=>'ಫೈಲ್ ಹೆಸರು ಖಾಲಿಯಾಗಿದೆ!','Folder does not exist: %s'=>'ಫೋಲ್ಡರ್ ಅಸ್ತಿತ್ವದಲ್ಲಿಲ್ಲ: %s','Can not create folder: %1$s. Error: %2$s'=>'ಫೋಲ್ಡರ್ ಅನ್ನು ರಚಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ: %1$s. ದೋಷ: %2$s','Folder is not writable: %s.'=>'ಫೋಲ್ಡರ್ ಬರೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ: %s.','File %s is not writable.'=>'%s ಫೈಲ್ ಅನ್ನು ಬರೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ.','Failed to write to %s.'=>'%s ಗೆ ಬರೆಯಲು ವಿಫಲವಾಗಿದೆ.','Guest Mode lists synced successfully.'=>'ಅತಿಥಿ ಮೋಡ್ ಪಟ್ಟಿಗಳು ಯಶಸ್ವಿಯಾಗಿ ಸಿಂಕ್ ಆಗಿವೆ.','Failed to sync Guest Mode lists.'=>'ಅತಿಥಿ ಮೋಡ್ ಪಟ್ಟಿಗಳನ್ನು ಸಿಂಕ್ ಮಾಡಲು ವಿಫಲವಾಗಿದೆ.','%1$s %2$s files left in queue'=>'%1$s %2$s ಫೈಲ್‌ಗಳು ಸರತಿ ಸಾಲಿನಲ್ಲಿ ಉಳಿದಿವೆ','Cancel'=>'ರದ್ದುಗೊಳಿಸಿ','Purge this page'=>'ಈ ಪುಟವನ್ನು ತೆರವುಗೊಳಿಸಿ','Mark this page as '=>'ಈ ಪುಟವನ್ನು ಗುರುತಿಸಿ','Forced cacheable'=>'ಬಲವಂತವಾಗಿ ಕ್ಯಾಶ್ ಮಾಡಬಹುದಾದ','Non cacheable'=>'ಕ್ಯಾಶ್ ಮಾಡಲು ಅಸಾಧ್ಯವಾದ','Private cache'=>'ಖಾಸಗಿ ಸಂಗ್ರಹ (ಪ್ರೈವೇಟ್ ಕ್ಯಾಶ್)','No optimization'=>'ಯಾವ ಆಪ್ಟಿಮೈಸೇಷನ್ ಇಲ್ಲ','More settings'=>'ಇನ್ನಷ್ಟು ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Purge All'=>'ಎಲ್ಲವನ್ನೂ ತೆರವುಗೊಳಿಸಿ','LSCache'=>'LSCache','CSS/JS Cache'=>'CSS/JS ಕ್ಯಾಷೆ','Cloudflare'=>'Cloudflare','Object Cache'=>'ಆಬ್ಜೆಕ್ಟ್ ಕ್ಯಾಶ್','Opcode Cache'=>'ಒಪಕೋಡ್ ಕ್ಯಾಶ್','Localized Resources'=>'ಸ್ಥಳೀಯಗೊಳಿಸಿದ ಸಂಪನ್ಮೂಲಗಳು','LQIP Cache'=>'LQIP ಕ್ಯಾಶ್','Gravatar Cache'=>'gravatar ಸಂಗ್ರಹ','Enable All Features'=>'ಎಲ್ಲಾ ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Zinn® Cache Engine Purge All'=>'Zinn® ಕ್ಯಾಚ್ ಎಂಜಿನ್ ಎಲ್ಲವನ್ನೂ ತೆರವುಗೊಳಿಸಿ','Manage'=>'ನಿರ್ವಹಿಸಿ','Remove all previous unfinished image optimization requests.'=>'ಎಲ್ಲಾ ಹಿಂದಿನ ಪೂರ್ಣಗೊಳ್ಳದ ಚಿತ್ರ ಆಪ್ಟಿಮೈಸೇಶನ್ ವಿನಂತಿಗಳನ್ನು ತೆಗೆದುಹಾಕಿ.','Clean Up Unfinished Data'=>'ಅಪೂರ್ಣಗೊಂಡ ಡೇಟಾವನ್ನು ತೆರವುಗೊಳಿಸಿ','Install %s'=>'%s ಅನ್ನು ಸ್ಥಾಪಿಸಿ','Install Now'=>'ಈಗ ಸ್ಥಾಪಿಸಿ','<a href="%1$s" %2$s>View version %3$s details</a> or <a href="%4$s" %5$s target="_blank">update now</a>.'=>'<a href="%1$s" %2$s>ಆವೃತ್ತಿ %3$s ವಿವರಗಳನ್ನು ವೀಕ್ಷಿಸಿ</a> ಅಥವಾ <a href="%4$s" %5$s target="_blank">ಈಗಲೇ ನವೀಕರಿಸಿ</a>.','View %1$s version %2$s details'=>'%1$s ಆವೃತ್ತಿ %2$s ವಿವರಗಳನ್ನು ವೀಕ್ಷಿಸಿ','Update %s now'=>'%s ಅನ್ನು ಈಗ ಅಪ್‌ಡೇಟ್ ಮಾಡಿ','Mobile Agent Rules'=>'ಮೊಬೈಲ್ ಏಜೆಂಟ್ ನಿಯಮಗಳು','<p>Please add/replace the following codes into the beginning of %1$s:</p> %2$s'=>'<p>ದಯವಿಟ್ಟು %1$s ನ ಆರಂಭದಲ್ಲಿ ಈ ಕೆಳಗಿನ ಕೋಡ್‌ಗಳನ್ನು ಸೇರಿಸಿ/ಬದಲಾಯಿಸಿ:</p> %2$s','Cleaned up unfinished data successfully.'=>'ಅಪೂರ್ಣ ಡೇಟಾವನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','Reset image optimization counter successfully.'=>'ಚಿತ್ರ ಆಪ್ಟಿಮೈಸೇಶನ್ ಕೌಂಟರ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಮರುಹೊಂದಿಸಲಾಗಿದೆ.','Destroy all optimization data successfully.'=>'ಎಲ್ಲಾ ಆಪ್ಟಿಮೈಸೇಶನ್ ಡೇಟಾವನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಅಳಿಸಲಾಗಿದೆ.','Rescanned successfully.'=>'ಯಶಸ್ವಿಯಾಗಿ ಮರು-ಸ್ಕ್ಯಾನ್ ಮಾಡಲಾಗಿದೆ.','Rescanned %d images successfully.'=>'%d ಚಿತ್ರಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಮರುಪರಿಶೀಲಿಸಲಾಗಿದೆ.','Calculated backups successfully.'=>'ಬ್ಯಾಕಪ್‌ಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಲೆಕ್ಕಹಾಕಲಾಗಿದೆ.','Removed backups successfully.'=>'ಬ್ಯಾಕಪ್‌ಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ತೆಗೆದುಹಾಕಲಾಗಿದೆ.','Switched images successfully.'=>'ಚಿತ್ರಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಬದಲಾಯಿಸಲಾಗಿದೆ.','Switched to optimized file successfully.'=>'ಆಪ್ಟಿಮೈಸ್ ಮಾಡಿದ ಫೈಲ್‌ಗೆ ಯಶಸ್ವಿಯಾಗಿ ಬದಲಾಯಿಸಲಾಗಿದೆ.','Disabled WebP file successfully.'=>'ವೆಬ್‌ಪಿ (WebP) ಫೈಲ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.','Enabled WebP file successfully.'=>'ವೆಬ್‌ಪಿ (WebP) ಫೈಲ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.','Disabled AVIF file successfully.'=>'AVIF ಫೈಲ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.','Enabled AVIF file successfully.'=>'AVIF ಫೈಲ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.','Restored original file successfully.'=>'ಮೂಲ ಫೈಲ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಮರುಸ್ಥಾಪಿಸಲಾಗಿದೆ.','Reset the optimized data successfully.'=>'ಆಪ್ಟಿಮೈಸ್ ಮಾಡಿದ ಡೇಟಾವನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಮರುಹೊಂದಿಸಲಾಗಿದೆ.','Started async image optimization request'=>'ಅಸಿಂಕ್ ಇಮೇಜ್ ಆಪ್ಟಿಮೈಸೇಶನ್ ವಿನಂತಿಯನ್ನು ಪ್ರಾರಂಭಿಸಲಾಗಿದೆ','Pull Cron is running'=>'ಪುಲ್ ಕ್ರೋನ್ ಚಾಲನೆಯಲ್ಲಿದೆ','Some optimized image file(s) has expired and was cleared.'=>'ಕೆಲವು ಆಪ್ಟಿಮೈಸ್ ಮಾಡಿರುವ ಚಿತ್ರ ಕಡತಗಳು (ಫೈಲ್) ಅವಧಿ ಮುಗಿದಿವೆ ಮತ್ತು ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','Pulled WebP image md5 does not match the notified WebP image md5.'=>'ಎಳೆದುಕೊಂಡ WebP ಚಿತ್ರದ md5 ಸೂಚಿಸಲಾದ WebP ಚಿತ್ರದ md5 ಗೆ ಹೊಂದಿಕೆಯಾಗುವುದಿಲ್ಲ.','Pulled AVIF image md5 does not match the notified AVIF image md5.'=>'ತೆಗೆದುಕೊಂಡ AVIF ಚಿತ್ರದ md5 ಸೂಚಿಸಲಾದ AVIF ಚಿತ್ರದ md5 ಗೆ ಹೊಂದಿಕೆಯಾಗುವುದಿಲ್ಲ.','One or more pulled images does not match with the notified image md5'=>'ಎಳೆದುಕೊಂಡಿರುವ ಒಂದು ಅಥವಾ ಹೆಚ್ಚಿನ ಚಿತ್ರಗಳು ಅಧಿಸೂಚನೆ ಕಳುಹಿಸಲಾದ ಚಿತ್ರದ md5 ನೊಂದಿಗೆ ಹೊಂದಿಕೆಯಾಗುತ್ತಿಲ್ಲ','Pushed %1$s to Cloud server, accepted %2$s.'=>'ಕ್ಲೌಡ್ ಸರ್ವರ್‌ಗೆ %1$s ತಳ್ಳಲಾಗಿದೆ, %2$s ಸ್ವೀಕರಿಸಲಾಗಿದೆ.','Cleared %1$s invalid images.'=>'%1$s ಅಮಾನ್ಯ ಚಿತ್ರಗಳನ್ನು ತೆರವುಗೊಳಿಸಲಾಗಿದೆ.','No valid image found in the current request.'=>'ಪ್ರಸ್ತುತ ವಿನಂತಿಯಲ್ಲಿ ಯಾವುದೇ ಮಾನ್ಯ ಚಿತ್ರ ಕಂಡುಬಂದಿಲ್ಲ.','No valid image found by Cloud server in the current request.'=>'ಪ್ರಸ್ತುತ ವಿನಂತಿಯಲ್ಲಿ ಕ್ಲೌಡ್ ಸರ್ವರ್‌ನಿಂದ ಯಾವುದೇ ಮಾನ್ಯವಾದ ಚಿತ್ರ ಕಂಡುಬಂದಿಲ್ಲ.','Import failed due to file error.'=>'ಫೈಲ್ ದೋಷದಿಂದಾಗಿ ಆಮದು ವಿಫಲವಾಗಿದೆ.','Imported setting file %s successfully.'=>'%s ಆಮದು ಮಾಡಿಕೊಂಡ ಸೆಟ್ಟಿಂಗ್ ಫೈಲ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಅಳವಡಿಸಲಾಗಿದೆ.','Reset successfully.'=>'ಯಶಸ್ವಿಯಾಗಿ ಮರುಹೊಂದಿಸಲಾಗಿದೆ.','Images not requested'=>'ಚಿತ್ರಗಳನ್ನು ವಿನಂತಿಸಲಾಗಿಲ್ಲ','Images ready to request'=>'ಚಿತ್ರಗಳು ವಿನಂತಿಸಲು ಸಿದ್ಧವಾಗಿವೆ','Images requested'=>'ಚಿತ್ರಗಳನ್ನು ವಿನಂತಿಸಲಾಗಿದೆ','Images notified to pull'=>'ಎಳೆಯಲು ಸೂಚನೆ ನೀಡಲಾದ ಚಿತ್ರಗಳು','Images optimized and pulled'=>'ಚಿತ್ರಗಳನ್ನು ಆಪ್ಟಿಮೈಸ್ ಮಾಡಲಾಗಿದೆ ಮತ್ತು ಪಡೆಯಲಾಗಿದೆ','Unable to automatically add %1$s as a Domain Alias for main %2$s domain, due to potential CDN conflict.'=>'ಸಂಭಾವ್ಯ CDN ಸಂಘರ್ಷದ ಕಾರಣದಿಂದ, ಮುಖ್ಯ %2$s ಡೊಮೇನ್‌ಗೆ %1$s ಅನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಡೊಮೇನ್ ಅಲಿಯಾಸ್ ಆಗಿ ಸೇರಿಸಲು ಸಾಧ್ಯವಾಗುತ್ತಿಲ್ಲ.','Unable to automatically add %1$s as a Domain Alias for main %2$s domain.'=>'ಮುಖ್ಯವಾದ %2$s ಡೊಮೇನ್‌ಗೆ %1$s ಅನ್ನು ಡೊ